begin;
create table public.measurement_retentions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,company_id uuid not null,measurement_id uuid not null,retention_type text not null check(retention_type in('inss','iss','rt','other')),description text,calculation_type text not null default 'percentage' check(calculation_type in('percentage','fixed')),rate numeric(9,6),fixed_amount numeric(18,2),base_amount numeric(18,2) not null default 0,amount numeric(18,2) not null default 0 check(amount>=0),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(tenant_id,company_id,measurement_id) references public.measurements(tenant_id,company_id,id) on delete restrict,check((calculation_type='percentage' and rate is not null and rate>=0 and fixed_amount is null) or(calculation_type='fixed' and fixed_amount is not null and fixed_amount>=0 and rate is null)),unique(tenant_id,company_id,id));
create index measurement_retentions_measurement_idx on public.measurement_retentions(tenant_id,company_id,measurement_id,retention_type);
create or replace function public.sync_measurement_retention() returns trigger language plpgsql set search_path='' as $$ declare v_status text;v_gross numeric(18,2);begin select status into v_status from public.measurements where tenant_id=new.tenant_id and company_id=new.company_id and id=new.measurement_id;if not found then raise exception 'measurement not found';end if;if v_status<>'draft' then raise exception 'retentions can only change while measurement is draft';end if;select coalesce(sum(gross_value),0) into v_gross from public.measurement_lines where tenant_id=new.tenant_id and company_id=new.company_id and measurement_id=new.measurement_id;new.base_amount:=v_gross;if new.calculation_type='percentage' then new.amount:=round(v_gross*new.rate/100,2);else new.amount:=new.fixed_amount;end if;return new;end $$;
revoke all on function public.sync_measurement_retention() from public,anon,authenticated;create trigger measurement_retentions_sync before insert or update on public.measurement_retentions for each row execute function public.sync_measurement_retention();
create or replace function public.guard_measurement_retention_delete() returns trigger language plpgsql set search_path='' as $$declare v_status text;begin select status into v_status from public.measurements where id=old.measurement_id;if v_status<>'draft' then raise exception 'retentions of closed/approved measurements are locked';end if;return old;end$$;revoke all on function public.guard_measurement_retention_delete() from public,anon,authenticated;create trigger measurement_retentions_delete_guard before delete on public.measurement_retentions for each row execute function public.guard_measurement_retention_delete();
create or replace function public.refresh_measurement_percentage_retentions() returns trigger language plpgsql set search_path='' as $$begin update public.measurement_retentions r set base_amount=x.gross,amount=round(x.gross*r.rate/100,2),updated_at=now() from(select m.id measurement_id,coalesce(sum(ml.gross_value),0) gross from public.measurements m left join public.measurement_lines ml on ml.tenant_id=m.tenant_id and ml.company_id=m.company_id and ml.measurement_id=m.id where m.id=coalesce(new.measurement_id,old.measurement_id) group by m.id)x where r.measurement_id=x.measurement_id and r.calculation_type='percentage';return coalesce(new,old);end$$;revoke all on function public.refresh_measurement_percentage_retentions() from public,anon,authenticated;create trigger measurement_lines_refresh_retentions after insert or update or delete on public.measurement_lines for each row execute function public.refresh_measurement_percentage_retentions();
create view public.measurement_financial_summary with(security_invoker=true) as select m.tenant_id,m.company_id,m.id measurement_id,m.contract_id,m.competence,m.status,coalesce(l.gross_amount,0)::numeric(18,2) gross_amount,coalesce(r.retained_amount,0)::numeric(18,2) retained_amount,(coalesce(l.gross_amount,0)-coalesce(r.retained_amount,0))::numeric(18,2) net_amount from public.measurements m left join(select tenant_id,company_id,measurement_id,sum(gross_value) gross_amount from public.measurement_lines group by tenant_id,company_id,measurement_id)l on l.tenant_id=m.tenant_id and l.company_id=m.company_id and l.measurement_id=m.id left join(select tenant_id,company_id,measurement_id,sum(amount) retained_amount from public.measurement_retentions group by tenant_id,company_id,measurement_id)r on r.tenant_id=m.tenant_id and r.company_id=m.company_id and r.measurement_id=m.id;
create trigger measurement_retentions_updated before update on public.measurement_retentions for each row execute function public.set_updated_at();alter table public.measurement_retentions enable row level security;create policy measurement_retentions_select on public.measurement_retentions for select to authenticated using(app_private.can_access_company(tenant_id,company_id));create policy measurement_retentions_write on public.measurement_retentions for all to authenticated using(app_private.can_access_company(tenant_id,company_id)) with check(app_private.can_access_company(tenant_id,company_id));
commit;